INSERT INTO TB_NOTICE (NTT_SN, NTT_SJ, NTT_CN, RDCNT, REGISTER_ID, REGIST_DT) VALUES (1, '공공시설 예약 이용 안내', '예약은 이용일 하루 전부터 30일 이내까지 신청할 수 있으며, 관리자 승인 후 확정됩니다.' || CHR(10) || '1인 1일 최대 2시간까지 예약할 수 있습니다.', 109, 'admin', SYSDATE + (-49.5069));
INSERT INTO TB_NOTICE (NTT_SN, NTT_SJ, NTT_CN, RDCNT, REGISTER_ID, REGIST_DT) VALUES (2, '예약 취소 규정', '승인된 예약도 이용일 전날까지 직접 취소할 수 있습니다.' || CHR(10) || '당일 취소는 시설 관리자에게 문의하세요.', 150, 'admin', SYSDATE + (-46.1514));
INSERT INTO TB_NOTICE (NTT_SN, NTT_SJ, NTT_CN, RDCNT, REGISTER_ID, REGIST_DT) VALUES (3, '구 시민운동장 보조구장 보수 공사 안내', '시설 보수로 당분간 신규 예약을 받지 않습니다. 공사가 끝나면 다시 안내하겠습니다.', 27, 'admin', SYSDATE + (-42.8689));
