INSERT INTO TB_NOTICE (NTT_SN, NTT_SJ, NTT_CN, RDCNT, REGISTER_ID, REGIST_DT) VALUES (5, '겨울철 야외 시설 이용 유의사항', '결빙 시 야외 운동장 이용이 제한될 수 있습니다. 이용 전 공지를 확인하세요.', 135, 'admin', SYSDATE + (-33.9534));
